  445+ /**
  446+  * @brief Returns the expired mails that hold items to their senders and deletes the rest.
  447+  *
  448+  * Runs once a day and at start-up.
  449+  *
  450+  * @param serverUp true if the server is already running, false when the server is started.
  451+  */
  452+ void ReturnOrDeleteOldMails(bool serverUp)
  453+ {
  454+     time_t curTime = time(NULL);
  455+     tm lt;
  456+     lt = safe_localtime(curTime);
  457+     uint64 basetime(curTime);
  458+     sLog.outString("Returning mails current time: hour: %d, minute: %d, second: %d ", lt.tm_hour, lt.tm_min, lt.tm_sec);
  459+ 
  460+     // delete all old mails without item and without body immediately, if starting server
  461+     if (!serverUp)
  462+     {
  463+         MailRepository::DeleteEmptyExpiredMails((uint64)basetime);
  464+     }
  465+ 
  466+     // Runs at start-up and on the daily mail timer inside World::Update, so both reads are staged here and the expired
  467+     // mails' returns and deletes happen in the callback. Slot 1 reads the expired mails' items in one join ordered by
  468+     // `mail_id`; the callback walks it as a cursor beside the mail rows, since both results ascend in that key.
  469+     MailRepository::QueueExpiredMailReads((uint64)basetime, [basetime, serverUp](SqlQueryHolder* h)
  470+                                           {
  471+                                               ReturnOrDeleteOldMailsCallback(std::unique_ptr<SqlQueryHolder>(h), basetime, serverUp);
  472+                                           });
  473+ }
  474+ 
  475+ /**
  476+  * @brief Returns or deletes the expired mails, once both reads have answered.
  477+  *
  478+  * Walks slot 1 as a cursor beside the mail rows. Every write it makes goes through PExecute, so nothing here runs a
  479+  * synchronous database call.
  480+  *
  481+  * @param holder   The two staged reads.
  482+  * @param basetime The expiry cut-off the reads were staged with, which the returned mails'
  483+  *                 new expiry and delivery times are computed from -- captured rather than
  484+  *                 recomputed, so a mail cannot be given a window that disagrees with the
  485+  *                 set it was selected in.
  486+  * @param serverUp The flag the caller passed, verbatim: it decides whether a mail whose
  487+  *                 receiver is online is left alone.
  488+  */
  489+ void ReturnOrDeleteOldMailsCallback(std::unique_ptr<SqlQueryHolder> holder, uint64 basetime, bool serverUp)
  490+ {
  491+     std::vector<ExpiredMailRow> mails = MailRepository::ExpiredMails(holder.get());
  492+     std::vector<ExpiredMailItemRow> mailItems = MailRepository::ExpiredMailItems(holder.get());
  493+ 
  494+     if (mails.empty())
  495+     {
  496+         BarGoLink bar(1);
  497+         bar.step();
  498+         sLog.outString(">> Only expired mails (need to be return or delete) or DB table `mail` is empty.");
  499+         sLog.outString();
  500+         return;                                             // no mail needs to be returned or deleted
  501+     }
  502+ 
  503+     BarGoLink bar(mails.size());
  504+     uint32 count = 0;
  505+ 
  506+     /// The item cursor: the next item row to read.
  507+     size_t nextItem = 0;
  508+ 
  509+     for (ExpiredMailRow const& mail : mails)
  510+     {
  511+         bar.step();
  512+ 
  513+         Mail* m = new Mail;
  514+         m->messageID = mail.id;
  515+ 
  516+         // Step over the item rows of any mail EARLIER than this one: a mail whose items
  517+         // were not consumed (its receiver was online) left its run standing.
  518+         while (nextItem < mailItems.size() && mailItems[nextItem].mailId < m->messageID)
  519+         {
  520+             ++nextItem;
  521+         }
  522+ 
  523+         m->messageType = mail.messageType;
  524+         m->sender = mail.sender;
  525+         m->receiverGuid = ObjectGuid(HIGHGUID_PLAYER, mail.receiver);
  526+         bool has_items = mail.hasItems;
  527+         m->expire_time = (time_t)mail.expireTime;
  528+         m->deliver_time = 0;
  529+         m->COD = mail.cod;
  530+         m->checked = mail.checked;
  531+         m->mailTemplateId = mail.mailTemplateId;
  532+ 
  533+         Player* pl = 0;
  534+         if (serverUp)
  535+         {
  536+             pl = sPlayerRegistry.Find(m->receiverGuid);
  537+         }
  538+         if (pl)
  539+         {
  540+             // this code will run very improbably (the time is between 4 and 5 am, in game is online a player, who has old mail
  541+             // his in mailbox and he has already listed his mails )
  542+             delete m;
  543+             continue;
  544+         }
  545+         // delete or return mail:
  546+         if (has_items)
  547+         {
  548+             // This mail's own run of the joined item rows: contiguous, because both
  549+             // reads ascend in `mail_id`.
  550+             while (nextItem < mailItems.size())
  551+             {
  552+                 ExpiredMailItemRow const& mailItem = mailItems[nextItem];
  553+                 if (mailItem.mailId != m->messageID)
  554+                 {
  555+                     break;
  556+                 }
  557+ 
  558+                 m->AddItem(mailItem.itemGuid, mailItem.itemTemplate);
  559+ 
  560+                 ++nextItem;
  561+             }
  562+             // if it is mail from non-player, or if it's already return mail, it shouldn't be returned, but deleted
  563+             if (m->messageType != MAIL_NORMAL || (m->checked & (MAIL_CHECK_MASK_COD_PAYMENT | MAIL_CHECK_MASK_RETURNED)))
  564+             {
  565+                 // mail open and then not returned
  566+                 for (MailItemInfoVec::iterator itr2 = m->items.begin(); itr2 != m->items.end(); ++itr2)
  567+                 {
  568+                     MailRepository::DeleteExpiredMailItem(itr2->item_guid);
  569+                 }
  570+             }
  571+             else
  572+             {
  573+                 // mail will be returned:
  574+                 MailRepository::ReturnExpiredMail(m->receiverGuid.GetCounter(), m->sender, (uint64)(basetime + 30 * DAY), (uint64)basetime,
  575+                                                   MAIL_CHECK_MASK_RETURNED, m->messageID);
  576+                 for (MailItemInfoVec::iterator itr2 = m->items.begin(); itr2 != m->items.end(); ++itr2)
  577+                 {
  578+                     // update receiver in mail items for its proper delivery, and in instance_item for avoid lost item at sender delete
  579+                     MailRepository::SetReturnedItemReceiver(m->sender, itr2->item_guid);
  580+                     MailRepository::SetReturnedItemOwner(m->sender, itr2->item_guid);
  581+                 }
  582+                 delete m;
  583+                 continue;
  584+             }
  585+         }
  586+ 
  587+         MailRepository::DeleteMailRow(m->messageID);
  588+         delete m;
  589+         ++count;
  590+     }
  591+ 
  592+     sLog.outString(">> Loaded %u mails", count);
  593+     sLog.outString();
  594+ }
